function Logo(){return <Link className="brand" to="/" aria-label="Proofline home"><span className="brand-mark"><Check size={17} strokeWidth={3}/></span><span>proofline<span className="brand-period">.</span></span></Link>}
function External({href,children}:{href:string;children:ReactNode}){return validUrl(href,true)?<a href={href} target="_blank" rel="noopener noreferrer">{children} <ExternalLink size={13}/></a>:<span>Invalid external link</span>}
function Badge({value}:{value:string}){return <span className={`badge badge-${value.toLowerCase()}`}><span/> {titleStatus(value)}</span>}
function Copy({value}:{value:string}){const [done,setDone]=useState(false);return <button className="copy" title="Copy address" aria-label="Copy address" onClick={()=>void navigator.clipboard.writeText(value).then(()=>{setDone(true);setTimeout(()=>setDone(false),1600)})}>{done?<Check size={14}/>:<Clipboard size={14}/>}</button>}
function WalletButton(){const w=useWallet();const [open,setOpen]=useState(false);return <><button className="button button-outline wallet-button" onClick={()=>setOpen(true)}><Wallet size={16}/>{w.account?short(w.account):'Connect wallet'}</button>{open&&<div className="overlay" onMouseDown={()=>setOpen(false)}><div className="modal" role="dialog" aria-modal="true" aria-labelledby="wallet-title" onMouseDown={e=>e.stopPropagation()}><button className="close" onClick={()=>setOpen(false)} aria-label="Close"><X/></button><div className="eyebrow">YOUR WALLET</div><h2 id="wallet-title">{w.account?'Connected account':'Connect to Proofline'}</h2>{w.account?<><p className="muted">Your wallet signs transactions. Proofline never asks for your private keys.</p><div className="info-row mono wrap">{w.account}<Copy value={w.account}/></div><p className="muted">Network: {w.chain.toLowerCase()===CONFIG.chainHex?'Studio Dev · 61997':`Wrong network (${w.chain || 'unknown'})`}</p>{w.chain.toLowerCase()!==CONFIG.chainHex&&<button className="button button-lime" onClick={()=>void w.switchNetwork()}>Switch network</button>}<button className="button button-outline" onClick={()=>{w.disconnect();setOpen(false)}}>Disconnect from app</button></>:<><p className="muted">Choose an installed browser wallet. Only connect one you trust.</p>{w.providers.length?w.providers.map((p:Provider,i)=><button className="wallet-option" key={i} onClick={()=>void w.connect(p)}><Wallet size={18}/>{p.isMetaMask?'MetaMask':`Browser wallet ${i+1}`}<ArrowRight size={16}/></button>):<div className="notice">No EIP-1193 wallet detected. Install a browser wallet and refresh this page.</div>}</>}{w.error&&<p className="error">{w.error}</p>}</div></div>}</>}
function TransactionModal(){const {state,busy,confirm,close,resume}=useTx();if(!state.open)return null;const pending=!!localStorage.getItem('proofline-pending-v1');return <div className="overlay"><div className="modal" role="dialog" aria-modal="true" aria-labelledby="tx-title"><button className="close" onClick={close} aria-label="Close"><X/></button><div className="eyebrow">GENLAYER TRANSACTION</div><h2 id="tx-title">{state.phase}</h2><p className="muted">A wallet signature is only the beginning. The contract state is authoritative after consensus and finalization.</p>{state.operation&&<div className="info-row"><span>Operation</span><span className="mono">{state.operation}</span></div>}{state.fee!==undefined&&<div className="info-row"><span>Estimated fee deposit</span><strong>{state.fee} GEN</strong></div>}{state.hash&&<div className="stack"><span className="tiny muted">TRANSACTION ID</span><span className="mono wrap">{state.hash} <Copy value={state.hash}/></span><External href={`${CONFIG.txExplorer}${state.hash}`}>Inspect transaction</External></div>}{state.error&&<p className="error">{state.error}</p>}<div className="modal-actions">{state.phase==='Review transaction'&&<button className="button button-lime" disabled={busy} onClick={()=>void confirm()}>Confirm &amp; sign <ArrowRight size={16}/></button>}{pending&&!busy&&<button className="button button-lime" onClick={resume}>Resume tracking</button>}<button className="button button-outline" onClick={close}>Close</button></div></div></div>}
function Shell({children}:{children:ReactNode}){const w=useWallet();const tx=useTx();const [menu,setMenu]=useState(false);return <><header className="topbar"><div className="top-inner"><Logo/><nav className={menu?'nav open':'nav'} aria-label="Main navigation"><NavLink onClick={()=>setMenu(false)} to="/explore">Explore</NavLink><NavLink onClick={()=>setMenu(false)} to="/claims">Claims</NavLink><NavLink onClick={()=>setMenu(false)} to="/metrics">Metrics</NavLink><NavLink onClick={()=>setMenu(false)} to="/dashboard">Dashboard</NavLink><NavLink onClick={()=>setMenu(false)} to="/my-work">My work</NavLink><NavLink onClick={()=>setMenu(false)} to="/activity">Activity</NavLink><NavLink onClick={()=>setMenu(false)} to="/how-it-works">How it works</NavLink></nav><div className="top-actions"><WalletButton/><button className="menu-button" onClick={()=>setMenu(!menu)} aria-label="Toggle navigation" aria-expanded={menu}>{menu?<X/>:<Menu/>}</button></div></div></header>{w.account&&w.chain.toLowerCase()!==CONFIG.chainHex&&<div className="network-warning">Wrong network. Switch to GenLayer Studio Dev (61997). <button onClick={()=>void w.switchNetwork()}>Switch network →</button></div>}{!tx.state.open&&localStorage.getItem('proofline-pending-v1')&&<div className="network-warning">A transaction may still be processing. <button onClick={tx.resume}>Resume tracking →</button></div>}<main>{children}</main><footer><div className="footer-inner"><Logo/><span>Clarity for work that matters.</span><div><External href={CONFIG.explorer}>Contract</External><Link to="/how-it-works">How it works</Link></div><span className="tiny">STUDIO DEV · 61997</span></div></footer><TransactionModal/></>}
function ArrowLink({to,children,secondary=false}:{to:string;children:ReactNode;secondary?:boolean}){return <Link className={`button ${secondary?'button-outline':'button-lime'}`} to={to}>{children}<ArrowRight size={17}/></Link>}
function Landing(){return <><section className="hero"><div className="hero-inner"><div className="hero-copy"><div className="eyebrow"><span className="live-dot"/> THE VERIFIABLE WORK PLATFORM <span className="line"/> BUILT ON GENLAYER</div><h1>Don't just promise the work.<br/><em>Prove it.</em></h1><p>Define clear milestones, submit verifiable evidence, and let independent GenLayer validators assess the work against the criteria.</p><div className="button-row"><ArrowLink to="/explore">Explore milestones</ArrowLink><ArrowLink to="/create" secondary>Create a milestone</ArrowLink></div><div className="hero-caption"><span>01 / 03</span><span>FROM AGREEMENT TO ACCOUNTABILITY</span></div></div><div className="hero-visual" aria-label="Illustration of the verification workflow"><div className="visual-head"><span><CircleDot size={15}/> PROOFLINE / VERIFICATION</span><span>ILLUSTRATIVE</span></div><div className="visual-content"><div className="visual-number">01 <span>/ MILESTONE</span></div><h3>Work, made<br/>verifiable<span>.</span></h3><div className="visual-label">ACCEPTANCE CRITERIA</div><div className="visual-rule"><span>01</span> Define the deliverable <Check size={15}/></div><div className="visual-rule"><span>02</span> Submit public evidence <Check size={15}/></div><div className="visual-rule"><span>03</span> Independent assessment <Check size={15}/></div><div className="visual-flow"><div><span>INPUT</span><strong>Evidence</strong></div><ArrowRight size={15}/><div><span>PROCESS</span><strong>Validators</strong></div><ArrowRight size={15}/><div><span>OUTPUT</span><strong>Consensus</strong></div></div></div><div className="visual-foot"><span>◇ &nbsp;GENLAYER INTELLIGENT CONTRACT</span><span>NOT A LIVE RESULT</span></div></div></div><div className="hero-bottom"><span>BUILT FOR WORK WITH CONSEQUENCES</span><span>FREELANCE &nbsp; / &nbsp; OPEN SOURCE &nbsp; / &nbsp; GRANTS &nbsp; / &nbsp; DAOS</span><ArrowDownRight size={18}/></div></section><section className="section ivory"><div className="section-head"><div><div className="eyebrow dark-eyebrow">THE PROBLEM / 01</div><h2>Good work deserves<br/><em>clear proof.</em></h2></div><p>When “done” means something different to everyone, trust gets expensive. Proofline makes the agreement—and the evidence—visible.</p></div><div className="three-grid"><article><span className="index">01 / DEFINE</span><h3>Agree on the outcome.</h3><p>Set a deliverable and precise, individually assessable acceptance criteria before the work starts.</p></article><article><span className="index">02 / SUBMIT</span><h3>Bring the evidence.</h3><p>Submit a public URL and give reviewers the context they need to assess the work.</p></article><article><span className="index">03 / VERIFY</span><h3>Make the decision visible.</h3><p>Independent GenLayer validators assess the evidence and record a consensus-backed result.</p></article></div></section><section className="section method"><div className="eyebrow">THE MECHANISM / 02</div><div className="section-head"><h2>Not another<br/><em>black box.</em></h2><div><p>GenLayer combines intelligent contracts with independent validator assessment. The contract stores the criteria, evidence references, and the agreed verification result.</p><Link className="text-link" to="/how-it-works">Understand the process <ArrowRight size={16}/></Link></div></div><div className="lifecycle"><div><span>01</span><strong>OPEN</strong><small>Define the work</small></div><ArrowRight/><div><span>02</span><strong>SUBMITTED</strong><small>Evidence received</small></div><ArrowRight/><div><span>03</span><strong>CONSENSUS</strong><small>Independent review</small></div><ArrowRight/><div><span>04</span><strong>OUTCOME</strong><small>Result or revision</small></div></div><p className="disclaimer">Consensus is not a guarantee of objective truth. Evidence accessibility does not prove authenticity. No payments or escrow are provided.</p></section><section className="section final-cta"><div className="eyebrow dark-eyebrow">THE LINE BETWEEN CLAIM AND PROOF</div><h2>Make good work<br/><em>impossible to miss.</em></h2><ArrowLink to="/explore">Explore milestones</ArrowLink></section></>}
function PageHead({eyebrow,title,desc,action}:{eyebrow:string;title:string;desc:string;action?:ReactNode}){return <div className="page-head"><div><div className="eyebrow"><span className="live-dot"/> {eyebrow}</div><h1>{title}<span className="accent">.</span></h1><p>{desc}</p></div>{action}</div>}
function DataNotice({updated,errors,total,shown}:{updated:string;errors:string[];total:number;shown:number}){return <><div className="data-notice"><span><span className="live-dot"/> LIVE CONTRACT DATA</span><span>{updated?`Loaded ${date(updated)} · reads may be cached up to 30s`:'Connecting to Studio Dev'}</span><span>{shown} / {total} records loaded</span></div>{errors.length>0&&<div className="notice error">Some contract reads failed: {errors.join(' · ')}. Refresh to retry.</div>}</>}
function Card({m}:{m:Milestone}){const left=m.max_submissions-m.submission_count;const expired=m.deadline*1000<Date.now();return <Link className="milestone-card" to={`/milestone/${m.id}`}><div className="card-top"><span className="mono micro">MILESTONE / {String(m.id).padStart(3,'0')}</span><Badge value={m.status}/></div><h3>{m.project_name}</h3><p>{m.task_description}</p><div className="card-details"><div><span>CREATOR</span><strong className="mono">{short(m.creator)}</strong></div><div><span>EXECUTOR</span><strong className="mono">{short(m.executor)}</strong></div><div><span>DEADLINE</span><strong>{date(m.deadline)}</strong></div><div><span>ATTEMPTS</span><strong>{m.submission_count} / {m.max_submissions} <small>· {left} left</small></strong></div></div><div className="card-foot"><span>{m.acceptance_criteria.length} criteria &nbsp; · &nbsp; {expired?'Deadline passed':'Deadline active'}</span><ArrowUpRight size={18}/></div></Link>}
function Empty({title,body,create=true}:{title:string;body:string;create?:boolean}){return <div className="empty"><div className="empty-icon"><Layers3 size={22}/></div><h3>{title}</h3><p>{body}</p>{create&&<ArrowLink to="/create">Create a milestone</ArrowLink>}</div>}
function Collection({mode='explore'}:{mode?:'explore'|'dashboard'|'my-work'|'activity'}){const data=useCollection();const w=useWallet();const [search,setSearch]=useState(''),[filter,setFilter]=useState('ALL'),[deadline,setDeadline]=useState('ALL'),[creator,setCreator]=useState(''),[executor,setExecutor]=useState(''),[sort,setSort]=useState('newest'),[tab,setTab]=useState('Created by me'),[view,setView]=useState<'grid'|'list'>('grid');
const list=useMemo(()=>{let a=[...data.items];if(mode==='dashboard'||mode==='my-work')a=a.filter(m=>same(m.creator,w.account)||same(m.executor,w.account));if(mode==='my-work')a=a.filter(m=>tab==='Created by me'?same(m.creator,w.account):tab==='Assigned to me'?same(m.executor,w.account):tab==='Needs my submission'?same(m.executor,w.account)&&m.status==='OPEN':tab==='Awaiting evaluation'?['SUBMITTED','INCONCLUSIVE'].includes(m.status):tab==='Requires revision'?same(m.executor,w.account)&&['REVISION_REQUIRED','INCONCLUSIVE'].includes(m.status):['APPROVED','REJECTED','EXHAUSTED'].includes(m.status));if(mode==='explore'){const q=search.toLowerCase();a=a.filter(m=>(m.project_name+' '+m.task_description).toLowerCase().includes(q)&&(filter==='ALL'||m.status===filter)&&(deadline==='ALL'||(deadline==='active'?m.deadline*1000>=Date.now():m.deadline*1000<Date.now()))&&(!creator||m.creator.toLowerCase().includes(creator.toLowerCase()))&&(!executor||m.executor.toLowerCase().includes(executor.toLowerCase())));a.sort((x,y)=>sort==='deadline'?x.deadline-y.deadline:sort==='status'?x.status.localeCompare(y.status):y.id-x.id);}return a;},[data.items,mode,w.account,tab,search,filter,deadline,creator,executor,sort]);
const info={explore:['DISCOVER / ON-CHAIN','Explore milestones','Real work, clear criteria, and outcomes you can inspect.'],dashboard:['YOUR WORKSPACE','Dashboard','A clear view of the work that needs your attention.'],'my-work':['YOUR WORKSPACE','My work','Milestones created by or assigned to your connected wallet.'],activity:['CONTRACT ACTIVITY','Activity','A view reconstructed from available contract state—not a complete event feed.']}[mode];
return <div className="container page"><PageHead eyebrow={info[0]} title={info[1]} desc={info[2]} action={<ArrowLink to="/create">Create milestone</ArrowLink>}/>{mode==='dashboard'&&<Suspense fallback={<p>Loading claim overview…</p>}><ClaimOverview/></Suspense>}{mode==='dashboard'&&<MetricOverview/>}<DataNotice updated={data.updated} errors={data.errors} total={data.total} shown={data.items.length}/>{(mode==='dashboard'||mode==='my-work')&&!w.account?<Empty title="Connect your wallet" body="Connect a wallet to see the milestones associated with your address." create={false}/>:<>{mode==='dashboard'&&<><div className="overview-grid">{[['Created',data.items.filter(m=>same(m.creator,w.account)).length],['Assigned',data.items.filter(m=>same(m.executor,w.account)).length],['Awaiting evidence',list.filter(m=>m.status==='OPEN').length],['Awaiting evaluation',list.filter(m=>m.status==='SUBMITTED').length],['Needs revision',list.filter(m=>m.status==='REVISION_REQUIRED').length],['Approved',list.filter(m=>m.status==='APPROVED').length],['Rejected',list.filter(m=>m.status==='REJECTED').length],['Inconclusive',list.filter(m=>m.status==='INCONCLUSIVE').length]].map(([label,n])=><div className="stat" key={label}><span>{label}</span><strong>{n}</strong></div>)}</div><p className="muted small">Counts reflect only the records loaded below. Load more for a more complete view.</p><div className="section-title"><h2>Associated milestones</h2><Link to="/my-work">View my work <ArrowRight size={15}/></Link></div></>}{mode==='explore'&&<div className="filters"><label className="search"><Search size={17}/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Search projects or tasks" aria-label="Search milestones"/></label><select aria-label="Filter by status" value={filter} onChange={e=>setFilter(e.target.value)}><option value="ALL">All statuses</option>{statuses.map(s=><option key={s} value={s}>{titleStatus(s)}</option>)}</select><select aria-label="Filter by deadline" value={deadline} onChange={e=>setDeadline(e.target.value)}><option value="ALL">All deadlines</option><option value="active">Active</option><option value="expired">Passed</option></select><select aria-label="Sort milestones" value={sort} onChange={e=>setSort(e.target.value)}><option value="newest">Newest first</option><option value="deadline">Deadline</option><option value="status">Status</option></select><input aria-label="Filter by creator address" placeholder="Creator address" value={creator} onChange={e=>setCreator(e.target.value)}/><input aria-label="Filter by executor address" placeholder="Executor address" value={executor} onChange={e=>setExecutor(e.target.value)}/><button className="button button-outline" onClick={()=>setView(view==='grid'?'list':'grid')}><Filter size={15}/>{view==='grid'?'List view':'Grid view'}</button></div>}{mode==='my-work'&&<div className="tabs">{['Created by me','Assigned to me','Needs my submission','Awaiting evaluation','Requires revision','Completed'].map(t=><button className={tab===t?'active':''} key={t} onClick={()=>setTab(t)}>{t}</button>)}</div>}{mode==='activity'&&<div className="notice">This view shows milestone records, creation times and current states. The contract does not expose a complete activity feed or every verification run.</div>}{data.loading&&data.items.length===0?<div className="skeleton-grid"><div/><div/><div/></div>:list.length?<div className={`card-grid ${view==='list'||mode==='activity'?'list-view':''}`}>{list.map(m=><Card key={m.id} m={m}/>)}</div>:<Empty title={data.errors.length&&!data.items.length?'Contract data unavailable':'Nothing to show yet'} body={data.errors.length&&!data.items.length?'The contract could not be read. Wait and refresh if the RPC is rate-limited.':data.total?'No loaded milestones match this view. Try a different filter or load more records.':'No milestones were returned by the contract.'} create={mode==='explore'}/>}<div className="list-actions"><button className="button button-outline" onClick={()=>void data.refresh()} disabled={data.loading}><RefreshCw size={15}/> Refresh</button>{data.next>0&&<button className="button button-outline" onClick={()=>void data.loadMore()} disabled={data.loading}>{data.loading?'Loading…':`Load more (${data.next} remaining)`}</button>}</div></>}</div>}

function Activity(){const data=useCollection();const [subs,setSubs]=useState<{sub:Submission;m:Milestone}[]>([]),[errors,setErrors]=useState<string[]>([]),[reading,setReading]=useState(false);useEffect(()=>{let alive=true;const load=async()=>{setReading(true);const jobs=data.items.flatMap(m=>Array.from({length:m.submission_count},(_,i)=>({m,attempt:i+1})));const found:{sub:Submission;m:Milestone}[]=[],failed:string[]=[];for(let i=0;i<jobs.length;i+=4){const group=jobs.slice(i,i+4);const results=await Promise.allSettled(group.map(j=>submission(j.m.id,j.attempt)));results.forEach((r,k)=>r.status==='fulfilled'?found.push({sub:r.value,m:group[k].m}):failed.push(`Milestone #${group[k].m.id}, attempt ${group[k].attempt}`));if(!alive)return;}setSubs(found);setErrors(failed);setReading(false)};void load();return()=>{alive=false}},[data.items]);const entries=[...data.items.map(m=>({key:`m${m.id}`,id:m.id,title:m.project_name,kind:'Milestone created',at:m.created_at,detail:`Current status: ${titleStatus(m.status)}`})),...subs.map(({m,sub})=>({key:`s${m.id}-${sub.attempt}`,id:m.id,title:m.project_name,kind:`Evidence submitted · attempt ${sub.attempt}`,at:sub.submitted_at,detail:`Submitted by ${short(sub.submitter)}`}))].sort((a,b)=>Date.parse(b.at)-Date.parse(a.at));return <div className="container page"><PageHead eyebrow="CONTRACT ACTIVITY" title="Activity" desc="A view reconstructed from available contract state—not a complete event feed." action={<ArrowLink to="/create">Create milestone</ArrowLink>}/><Suspense fallback={<p>Loading claim activity…</p>}><ClaimOverview activity/></Suspense><DataNotice updated={data.updated} errors={[...data.errors,...errors]} total={data.total} shown={data.items.length}/><div className="notice">Creation and submission timestamps are reconstructed for loaded milestones. This is not a full event history; earlier evaluation runs are not exposed by the contract.</div>{entries.length?<div className="activity-list">{entries.map(e=><Link className="activity-item" to={`/milestone/${e.id}`} key={e.key}><span className="activity-icon"><Clock3 size={17}/></span><div><div className="eyebrow">{e.kind}</div><h3>{e.title}</h3><p>{e.detail} · Milestone #{e.id}</p></div><div className="activity-time">{date(e.at)} <ArrowUpRight size={16}/></div></Link>)}</div>:data.loading||reading?<div className="skeleton tall"/>:<Empty title={data.errors.length?"Activity unavailable":"No activity found"} body={data.errors.length?"The contract could not be read. Refresh to try again.":"No creation or submission records are available in the loaded milestones."} create={false}/>}<div className="list-actions"><button className="button button-outline" disabled={data.loading} onClick={()=>void data.refresh()}><RefreshCw size={15}/> Refresh</button>{data.next>0&&<button className="button button-outline" disabled={data.loading} onClick={()=>void data.loadMore()}>Load more ({data.next} remaining)</button>}</div></div>}

function useDetail(id:number){const [m,setM]=useState<Milestone|null>(null),[s,setS]=useState<Status|null>(null),[subs,setSubs]=useState<Submission[]>([]),[vers,setVers]=useState<Verification[]>([]),[loading,setLoading]=useState(true),[error,setError]=useState(''),[warnings,setWarnings]=useState<string[]>([]),[updated,setUpdated]=useState('');useEffect(()=>{let alive=true;const load=async()=>{setLoading(true);setError('');try{if(!Number.isSafeInteger(id)||id<1)throw Error('Invalid milestone ID.');const [mm,ss]=await Promise.all([milestone(id),status(id)]);const subResults=await Promise.allSettled(Array.from({length:mm.submission_count},(_,i)=>submission(id,i+1)));const subItems=subResults.flatMap(r=>r.status==='fulfilled'?[r.value]:[]);const verResults=await Promise.allSettled(subItems.filter(x=>x.evaluation_runs>0).map(x=>verification(id,x.attempt)));if(alive){setM(mm);setS(ss);setSubs(subItems);setVers(verResults.flatMap(r=>r.status==='fulfilled'?[r.value]:[]));setWarnings([...subResults,...verResults].flatMap(r=>r.status==='rejected'?[message(r.reason)]:[]));setUpdated(new Date().toISOString());}}catch(e){if(alive)setError(message(e));}finally{if(alive)setLoading(false);}};void load();const handler=()=>{invalidateReads();void load();};window.addEventListener('proofline-refresh',handler);return()=>{alive=false;window.removeEventListener('proofline-refresh',handler)}},[id]);return {m,s,subs,vers,loading,error,warnings,updated,refresh:()=>window.dispatchEvent(new Event('proofline-refresh'))};}
function DetailState({loading,error}:{loading:boolean;error:string}){return loading?<div className="container page"><div className="skeleton tall"/></div>:<div className="container page"><div className="notice error">Unable to read this milestone: {error||'No data returned'}. <button className="text-link" onClick={()=>window.dispatchEvent(new Event('proofline-refresh'))}>Retry read</button> · <Link to="/explore">Return to explore</Link></div></div>}
function Criteria({criteria,report}:{criteria:string[];report?:Verification}){return <div className="criteria">{criteria.map((c,i)=>{const r=report?.criteria_results[i];return <div className="criterion" key={i}><span className="criterion-num">{String(i+1).padStart(2,'0')}</span><div><strong>{c}</strong>{r&&<p>{r.explanation}</p>}</div><span className={`criterion-state ${r?.status?.toLowerCase()||''}`}>{r?.status||'PENDING'}</span></div>})}</div>}
function Detail(){const {id:raw}=useParams();const id=Number(raw),d=useDetail(id),w=useWallet(),tx=useTx();if(!d.m||!d.s)return <DetailState loading={d.loading} error={d.error}/>;const {m,s}=d;const latest=d.subs.find(x=>x.attempt===m.submission_count),report=d.vers.find(x=>x.attempt===m.submission_count);return <div className="container page"><div className="crumb"><Link to="/explore">Explore</Link><ChevronRight size={14}/> Milestone {id}</div><PageHead eyebrow={`MILESTONE / ${String(id).padStart(3,'0')}`} title={m.project_name} desc={m.task_description} action={<Badge value={s.status}/>}/><div className="data-notice"><span><span className="live-dot"/> CONTRACT READ</span><span>Loaded {date(d.updated)} · reads may be cached up to 30s</span><button onClick={d.refresh}><RefreshCw size={14}/> Refresh</button></div>{d.error&&<div className="notice error">Refresh failed; showing previously loaded data: {d.error}</div>}{d.warnings.length>0&&<div className="notice error">Some history could not be read: {d.warnings.join(' · ')}</div>}<Suspense fallback={<p>Loading linked claims…</p>}><MilestoneClaims id={id}/><p className="notice">Metrics provide supporting intelligence; they do not change milestone decisions. <Link to={`/metrics/new?milestone=${id}`}>Create a related metric →</Link> · <Link to={`/metrics?ref=proofline%3Amilestone%3A${id}`}>Find related metrics →</Link></p></Suspense><div className="detail-grid"><div><section className="panel"><div className="panel-heading"><div><div className="eyebrow">01 / THE AGREEMENT</div><h2>Work to be done</h2></div><FileCheck2 size={22}/></div><p>{m.task_description}</p><div className="subsection"><div className="tiny muted">EXPECTED DELIVERABLE</div><p>{m.expected_deliverable}</p></div>{m.reference_url&&<div className="subsection"><div className="tiny muted">REFERENCE</div><p><External href={m.reference_url}>View reference</External></p></div>}</section><section className="panel"><div className="panel-heading"><div><div className="eyebrow">02 / ACCEPTANCE CRITERIA</div><h2>What success looks like</h2></div><span className="mono muted">{String(m.acceptance_criteria.length).padStart(2,'0')} UNITS</span></div><Criteria criteria={m.acceptance_criteria} report={report}/>{!report&&<p className="muted small">Criteria remain pending until a verification is recorded for the latest attempt.</p>}</section><section className="panel"><div className="panel-heading"><div><div className="eyebrow">03 / RECORD</div><h2>Submission history</h2></div></div>{d.subs.length?d.subs.map(sub=>{const v=d.vers.find(x=>x.attempt===sub.attempt);return <div className="history" key={sub.attempt}><div><span className="index">ATTEMPT {String(sub.attempt).padStart(2,'0')}</span><h3>{v?titleStatus(v.decision):'Awaiting verification'}</h3><p className="muted">Submitted {date(sub.submitted_at)} · {sub.evaluation_runs} evaluation run(s)</p><External href={sub.evidence_url}>View evidence</External>{sub.explanation&&<p>{sub.explanation}</p>}{sub.supplementary_url&&<External href={sub.supplementary_url}>Supplementary evidence</External>}</div>{v&&<Link className="text-link" to={`/milestone/${id}/verification?attempt=${sub.attempt}`}>View report <ArrowRight size={15}/></Link>}</div>}):<p className="muted">No submissions have been recorded.</p>}<p className="muted small">Only the latest verification for each attempt is exposed; earlier runs are not displayed.</p></section></div><aside><section className="panel sticky-panel"><div className="eyebrow">MILESTONE STATUS</div><div className="aside-status"><Badge value={s.status}/></div><div className="progress-line"><span className="done"/><span className={m.submission_count?'done':''}/><span className={d.vers.length?'done':''}/></div><div className="progress-labels"><span>DEFINED</span><span>SUBMITTED</span><span>ASSESSED</span></div><div className="info-row"><span>Attempts</span><strong>{s.submission_count} / {s.max_submissions}</strong></div><div className="info-row"><span>Remaining</span><strong>{s.attempts_left}</strong></div><div className="info-row"><span>Deadline</span><strong>{date(s.deadline)}</strong></div><div className="info-row"><span>Deadline state</span><strong>{s.deadline_passed?'Passed':'Active'}</strong></div><div className="info-row"><span>Creator</span><span className="mono">{short(m.creator)} <Copy value={m.creator}/></span></div><div className="info-row"><span>Executor</span><span className="mono">{short(m.executor)} {m.executor&&<Copy value={m.executor}/>}</span></div><div className="info-row"><span>Created</span><strong>{date(m.created_at)}</strong></div><div className="next-action"><span>NEXT ACTION / CONTRACT</span><p>{s.next_action}</p></div><div className="action-stack">{canSubmit(m,s,w.account)&&<ArrowLink to={`/milestone/${id}/submit`}>Submit evidence</ArrowLink>}{canRevise(m,s,w.account)&&<ArrowLink to={`/milestone/${id}/submit`}>Submit revision</ArrowLink>}{canEvaluate(m,s,w.account,latest)&&<button className="button button-lime" disabled={tx.busy} onClick={()=>void tx.start({functionName:'evaluate_milestone',args:[id]},async()=>{const [freshStatus,freshSub,freshVerification]=await Promise.all([status(id,true),submission(id,0,true),verification(id,0,true)]);if(freshSub.attempt!==latest?.attempt||freshSub.evaluation_runs<=(latest?.evaluation_runs??0)||freshVerification.attempt!==freshSub.attempt||freshStatus.milestone_id!==id)throw Error('The updated evaluation could not yet be confirmed by fresh reads.');d.refresh();})}>Request evaluation <ArrowRight size={16}/></button>}{d.vers.length>0&&<ArrowLink secondary to={`/milestone/${id}/verification`}>Verification report</ArrowLink>}{!w.account&&<p className="muted small">Connect a wallet to see available actions.</p>}</div><p className="muted small">Actions depend on the latest contract state and account. The contract enforces authorization.</p></section></aside></div></div>}
function Evidence(){const {id:raw}=useParams();const id=Number(raw),d=useDetail(id),w=useWallet(),tx=useTx(),nav=useNavigate();const [url,setUrl]=useState(''),[explanation,setExplanation]=useState(''),[supp,setSupp]=useState(''),[confirmed,setConfirmed]=useState(false),[error,setError]=useState('');if(!d.m||!d.s)return <DetailState loading={d.loading} error={d.error}/>;const revision=['REVISION_REQUIRED','INCONCLUSIVE'].includes(d.s.status);const permitted=revision?canRevise(d.m,d.s,w.account):canSubmit(d.m,d.s,w.account);const run=async()=>{if(!validUrl(url,true)||!validUrl(supp)||url===supp||explanation.length>1500){setError('Use distinct public HTTP(S) URLs of up to 500 characters. Explanations must be at most 1,500 characters.');return;}if(!confirmed){setError('Confirm the evidence checklist first.');return;}setError('');await tx.start({functionName:revision?'submit_revision':'submit_evidence',args:[id,url.trim(),explanation.trim(),supp.trim()]},async()=>{const [freshMilestone,freshStatus,freshSubmission]=await Promise.all([milestone(id,true),status(id,true),submission(id,0,true)]);if(freshMilestone.submission_count<=d.m!.submission_count||freshSubmission.evidence_url!==url.trim()||freshStatus.milestone_id!==id)throw Error('The new submission could not yet be confirmed by fresh reads.');d.refresh();nav(`/milestone/${id}`)});};return <div className="container page narrow"><div className="crumb"><Link to={`/milestone/${id}`}>Milestone {id}</Link><ChevronRight size={14}/> Evidence</div><PageHead eyebrow="SUBMISSION / EVIDENCE" title={revision?'Submit a revision':'Submit evidence'} desc={`For ${d.m.project_name} · attempt ${d.m.submission_count+1} of ${d.m.max_submissions}`}/>{!permitted&&<div className="notice error">The current wallet and contract state do not permit this submission. Check the assigned executor, deadline and remaining attempts.</div>}<section className="panel form"><label>Primary evidence URL <span>Required</span><input value={url} onChange={e=>setUrl(e.target.value)} type="url" placeholder="https://github.com/…" maxLength={500}/></label><label>Explanation <span>Optional · max 1,500 characters</span><textarea rows={5} value={explanation} onChange={e=>setExplanation(e.target.value)} maxLength={1500} placeholder="Help the validators understand what to look for."/></label><label>Supplementary URL <span>Optional</span><input value={supp} onChange={e=>setSupp(e.target.value)} type="url" placeholder="https://…" maxLength={500}/></label><div className="notice"><strong>Make your evidence accessible.</strong><p>Validators retrieve evidence with HTTP GET. Avoid private repositories, logins, paywalls and JavaScript-only pages. A reachable page does not prove authenticity.</p></div><label className="check-label"><input type="checkbox" checked={confirmed} onChange={e=>setConfirmed(e.target.checked)}/> I checked that the evidence is public and addresses the stored criteria.</label>{error&&<p className="error">{error}</p>}<button className="button button-lime" disabled={!permitted||tx.busy} onClick={()=>void run()}>Review transaction <ArrowRight size={16}/></button></section></div>}
function VerificationPage(){const {id:raw}=useParams();const id=Number(raw),d=useDetail(id);const query=new URLSearchParams(window.location.search);const attempt=Number(query.get('attempt')||0);if(!d.m||!d.s)return <DetailState loading={d.loading} error={d.error}/>;const v=attempt?d.vers.find(x=>x.attempt===attempt):[...d.vers].sort((a,b)=>b.attempt-a.attempt)[0];return <div className="container page"><div className="crumb"><Link to={`/milestone/${id}`}>Milestone {id}</Link><ChevronRight size={14}/> Verification report</div><PageHead eyebrow="GENLAYER / VERIFICATION REPORT" title="The evidence, assessed" desc={`Contract-recorded assessment for ${d.m.project_name}.`}/>{!v?<Empty title="No verification available" body={d.warnings.length?'A verification read failed. Return to the milestone and refresh.':'There is no recorded verification for this attempt.'} create={false}/>:<div className="detail-grid"><div><section className="panel outcome"><div className="eyebrow">CONSENSUS-ACCEPTED RECORD</div><div className="outcome-head"><div><h2>{titleStatus(v.decision)}</h2><p>{v.decision==='APPROVED'?'The contract recorded an approved assessment.':v.decision==='REJECTED'?'The contract recorded a rejected assessment.':v.decision==='INCONCLUSIVE'?'The evidence could not be assessed conclusively. This is not approval.':'The assessment identified work that needs revision.'}</p></div><Badge value={v.decision}/></div><p>{v.evidence_summary||'No summary returned.'}</p></section><section className="panel"><div className="panel-heading"><div><div className="eyebrow">01 / EVIDENCE CHECKS</div><h2>What was found</h2></div></div><div className="checks">{[['Evidence accessible',v.evidence_accessible],['Evidence relevant',v.evidence_relevant],['Deliverable present',v.deliverable_present],['Evidence sufficient',v.evidence_sufficient]].map(([label,value])=><div key={String(label)}><span>{label}</span><strong className={value?'yes':'no'}>{value?'YES':'NO'}</strong></div>)}</div></section><section className="panel"><div className="panel-heading"><div><div className="eyebrow">02 / CRITERION ASSESSMENT</div><h2>The details matter</h2></div></div><Criteria criteria={v.criteria_results.map(r=>r.criterion)} report={v}/></section><section className="panel"><div className="eyebrow">03 / NOTES FROM ASSESSMENT</div><h2>What remains unverified</h2><h3>Missing items</h3>{v.missing_items.length?<ul>{v.missing_items.map((x,i)=><li key={i}>{x}</li>)}</ul>:<p className="muted">None reported.</p>}<h3>Unverified claims</h3>{v.unverified_claims.length?<ul>{v.unverified_claims.map((x,i)=><li key={i}>{x}</li>)}</ul>:<p className="muted">None reported.</p>}</section></div><aside><section className="panel"><div className="eyebrow">REPORT METADATA</div><div className="info-row"><span>Verification status</span><strong>{v.verification_status}</strong></div><div className="info-row"><span>Attempt / run</span><strong>{v.attempt} / {v.run}</strong></div><div className="info-row"><span>Evaluator</span><span className="mono">{short(v.evaluator)} <Copy value={v.evaluator}/></span></div><div className="info-row"><span>Verified</span><strong>{date(v.verified_at)}</strong></div><div className="info-row"><span>Confidence</span><strong>{v.confidence}</strong></div><p className="muted small">Confidence is informational, not a probability of approval or a validator consensus percentage.</p><External href={CONFIG.explorer}>Inspect contract</External></section><section className="panel"><div className="eyebrow">HOW GENLAYER WORKS</div><p>A leader and independent validators retrieve and assess the evidence. The contract stores a result after the required consensus. Validator identities and individual scores are not exposed here.</p><Link className="text-link" to="/how-it-works">Learn about verification <ArrowRight size={15}/></Link></section></aside></div>}</div>}
function Create(){const w=useWallet(),tx=useTx(),nav=useNavigate();const creating=useRef(false);const [step,setStep]=useState(0),[project,setProject]=useState(''),[task,setTask]=useState(''),[deliverable,setDeliverable]=useState(''),[criteria,setCriteria]=useState(['']),[reference,setReference]=useState(''),[deadline,setDeadline]=useState(''),[max,setMax]=useState(3),[executor,setExecutor]=useState(''),[agree,setAgree]=useState(false),[error,setError]=useState('');const steps=['Project','Criteria','Timing','Executor','Review'];const validate=(s:number)=>{if(s===0&&(!project.trim()||project.trim().length>120||task.trim().length<20||task.trim().length>2000||deliverable.trim().length<10||deliverable.trim().length>1000))return 'Project is required; task needs 20–2,000 characters and deliverable 10–1,000.';if(s===1)return criteriaError(criteria);if(s===2){const t=Math.floor(new Date(deadline).getTime()/1000),now=Math.floor(Date.now()/1000);if(!validUrl(reference))return 'Reference must be a public HTTP(S) URL (max 500 characters).';if(!Number.isFinite(t)||t<=now||t>now+2*365*86400)return 'Choose a future deadline within two years.';if(!Number.isInteger(max)||max<1||max>5)return 'Maximum submissions must be between 1 and 5.';}if(s===3&&executor&&(!addressValid(executor)||same(executor,w.account)))return 'Enter a valid executor address different from the creator, or leave it blank.';return '';};const next=()=>{const e=validate(step);setError(e);if(!e)setStep(step+1)};
const run=async()=>{for(let s=0;s<4;s++){const e=validate(s);if(e){setError(e);setStep(s);return;}}if(!agree){setError('Confirm the review before continuing.');return;}setError('');if(creating.current)return;creating.current=true;let before:number;try{before=await count(true)}catch(e){creating.current=false;setError(`Cannot read the milestone count: ${message(e)}`);return;}const c=criteria.map(x=>x.trim()).filter(Boolean),deadlineSeconds=Math.floor(new Date(deadline).getTime()/1000),creator=w.account;await tx.start({functionName:'create_milestone',args:[project.trim(),task.trim(),deliverable.trim(),c.join('\n'),reference.trim(),deadlineSeconds,max,executor.trim()]},async()=>{const end=await count(true);const matches:Milestone[]=[];for(let id=before+1;id<=Math.min(end,before+50);id++){const m=await milestone(id,true);if(same(m.creator,creator)&&m.project_name===project.trim()&&m.task_description===task.trim()&&m.deadline===deadlineSeconds&&m.acceptance_criteria.join('\n')===c.join('\n'))matches.push(m);}window.dispatchEvent(new Event('proofline-refresh'));if(matches.length===1&&end<=before+50)nav(`/milestone/${matches[0].id}`);else nav('/explore');});creating.current=false;};return <div className="container page"><div className="crumb"><Link to="/explore">Explore</Link><ChevronRight size={14}/> Create</div><PageHead eyebrow="NEW MILESTONE / ON-CHAIN" title="Define the work" desc="Make the agreement clear before the work begins."/><div className="create-grid"><aside className="steps">{steps.map((s,i)=><div className={step===i?'current':i<step?'completed':''} key={s}><span>{i<step?<Check size={14}/>:String(i+1).padStart(2,'0')}</span><strong>{s}</strong></div>)}<p>Milestones are public and their final states are immutable. No payment or escrow is included.</p></aside><section className="panel form"><div className="eyebrow">STEP {String(step+1).padStart(2,'0')} / 05</div><h2>{['Start with the outcome','Make success measurable','Set the boundaries','Assign the work','Review your milestone'][step]}</h2>{step===0&&<><label>Project name <span>Up to 120 characters</span><input maxLength={120} value={project} onChange={e=>setProject(e.target.value)} placeholder="e.g. Community documentation"/></label><label>Task description <span>20–2,000 characters</span><textarea rows={5} maxLength={2000} value={task} onChange={e=>setTask(e.target.value)} placeholder="Describe what needs to be done."/></label><label>Expected deliverable <span>10–1,000 characters</span><textarea rows={3} maxLength={1000} value={deliverable} onChange={e=>setDeliverable(e.target.value)} placeholder="What should the finished work contain?"/></label></>}{step===1&&<><p className="muted">Specific, observable criteria help validators assess the same agreement. Each needs at least 15 characters and 3 words.</p>{criteria.map((c,i)=><div className="criteria-input" key={i}><span>{String(i+1).padStart(2,'0')}</span><textarea value={c} maxLength={300} rows={2} aria-label={`Criterion ${i+1}`} onChange={e=>setCriteria(criteria.map((x,j)=>j===i?e.target.value:x))} placeholder="Describe one observable requirement"/><button className="copy" aria-label={`Delete criterion ${i+1}`} disabled={criteria.length===1} onClick={()=>setCriteria(criteria.filter((_,j)=>i!==j))}><X size={17}/></button></div>)}<button className="text-link" disabled={criteria.length>=10} onClick={()=>setCriteria([...criteria,''])}><Plus size={16}/> Add criterion ({criteria.length}/10)</button><div className="notice"><strong>Example</strong><p>GitHub repository contains a working React application with a responsive dashboard and a documented deployment process.</p></div></>}{step===2&&<><label>Reference URL <span>Optional</span><input type="url" value={reference} onChange={e=>setReference(e.target.value)} placeholder="https://…" maxLength={500}/></label><label>Deadline <span>Local time · within two years</span><input type="datetime-local" value={deadline} onChange={e=>setDeadline(e.target.value)}/></label><label>Maximum submissions <span>1 to 5 attempts</span><input type="number" min="1" max="5" value={max} onChange={e=>setMax(Number(e.target.value))}/></label><p className="muted small">Reference URLs are supplied as text to the judge; they are not fetched as evidence.</p></>}{step===3&&<><label>Executor address <span>Optional</span><input className="mono" value={executor} onChange={e=>setExecutor(e.target.value)} placeholder="0x…"/></label><div className="notice"><strong>Unassigned work can be claimed.</strong><p>If left blank, the first valid submitter becomes the executor. This can be front-run; assigning an address is recommended.</p></div></>}{step===4&&<><div className="review-row"><span>Project</span><strong>{project}</strong></div><div className="review-row"><span>Task</span><strong>{task}</strong></div><div className="review-row"><span>Deliverable</span><strong>{deliverable}</strong></div><div className="review-row"><span>Criteria</span><strong>{criteria.filter(Boolean).map((x,i)=><span className="review-criterion" key={i}>{i+1}. {x}</span>)}</strong></div><div className="review-row"><span>Reference</span><strong className="wrap">{reference||'None'}</strong></div><div className="review-row"><span>Deadline</span><strong>{deadline?date(new Date(deadline).toISOString()):'—'}</strong></div><div className="review-row"><span>Max submissions</span><strong>{max}</strong></div><div className="review-row"><span>Executor</span><strong className="mono wrap">{executor||'Unassigned'}</strong></div><div className="review-row"><span>Network</span><strong>Studio Dev · 61997</strong></div><div className="review-row"><span>Contract</span><strong className="mono wrap">{CONFIG.contract}</strong></div><label className="check-label"><input type="checkbox" checked={agree} onChange={e=>setAgree(e.target.checked)}/> I understand this milestone will be public and created on-chain.</label>{!w.account&&<div className="notice">Connect a wallet before preparing the transaction.</div>}</>}{error&&<p className="error">{error}</p>}<div className="form-actions">{step>0&&<button className="button button-outline" onClick={()=>{setStep(step-1);setError('')}}>Back</button>}{step<4?<button className="button button-lime" onClick={next}>Continue <ArrowRight size={16}/></button>:<button className="button button-lime" disabled={!w.account||tx.busy} onClick={()=>void run()}>Review transaction <ArrowRight size={16}/></button>}</div></section></div></div>}
function How(){return <div className="container page educational"><PageHead eyebrow="THE PROOFLINE METHOD" title="Trust, with a trail" desc="A practical guide to criteria, evidence, and independent verification."/><div className="lifecycle"><div><span>01</span><strong>OPEN</strong><small>Create a milestone</small></div><ArrowRight/><div><span>02</span><strong>SUBMITTED</strong><small>Share evidence</small></div><ArrowRight/><div><span>03</span><strong>ASSESS</strong><small>Validators review</small></div><ArrowRight/><div><span>04</span><strong>OUTCOME</strong><small>Result or revision</small></div></div><div className="education-grid"><section className="panel"><div className="eyebrow">01 / THE PROCESS</div><h2>From work to evidence</h2>{[['Create the milestone','A creator defines the project, deliverable, deadline and submission limit.'],['Define acceptance criteria','Each specific criterion is stored with the milestone.'],['Submit public evidence','The assigned executor—or first valid submitter if unassigned—submits a URL and explanation.'],['Request independent evaluation','The creator or executor requests evaluation. A leader and validators independently retrieve and assess the evidence.'],['Reach a consensus outcome','The contract records an approved, rejected, revision-required or inconclusive assessment after consensus. A transaction can instead be undetermined, leaving state unchanged.'],['Revise or conclude','The executor can revise when permitted. Inconclusive assessments may also be re-evaluated, subject to limits.']].map(([a,b],i)=><div className="explain-row" key={a}><span className="index">0{i+1}</span><div><h3>{a}</h3><p>{b}</p></div></div>)}</section><aside><section className="panel"><div className="eyebrow">02 / IMPORTANT LIMITS</div><h2>Verification isn't certainty.</h2><p>A reachable page does not prove authenticity. The contract stores a verdict and evidence URLs, not a complete snapshot. Pages can change.</p><p>AI assessment can be wrong, and consensus does not guarantee objective truth. Private, paywalled, large, or JavaScript-rendered pages may not be readable.</p><p>There are no payments, escrow, user profiles, built-in notifications, or comprehensive event history. Studio Dev is a preview network that can reset.</p></section><section className="panel"><div className="eyebrow">03 / WHY GENLAYER</div><h3>Beyond a single reviewer</h3><p>Manual review relies on a person; centralized AI relies on one service. GenLayer's leader and validators independently assess evidence and compare decision-relevant results. It adds distributed agreement, not a guarantee of correctness.</p><External href={CONFIG.explorer}>View the contract</External></section></aside></div></div>}
function NotFound(){return <div className="container page"><Empty title="Page not found" body="This route does not exist." create={false}/><ArrowLink to="/explore">Explore milestones</ArrowLink></div>}
export function App(){return <WalletProvider><TransactionProvider><Shell><Routes><Route path="/" element={<Landing/>}/><Route path="/claims" element={<Suspense fallback={<p>Loading claims…</p>}><ClaimsExplorer/></Suspense>}/><Route path="/claims/new" element={<Suspense fallback={<p>Loading claim form…</p>}><CreateClaim/></Suspense>}/><Route path="/claims/:id" element={<Suspense fallback={<p>Loading claim…</p>}><ClaimDetail/></Suspense>}/><Route path="/claims/:id/:section" element={<Suspense fallback={<p>Loading claim…</p>}><ClaimDetail/></Suspense>}/><Route path="/metrics" element={<div className="metric-workspace"><MetricsExplore/></div>}/><Route path="/metrics/mine" element={<div className="metric-workspace"><MetricsExplore dashboard/></div>}/><Route path="/metrics/methodology" element={<MetricMethodology/>}/><Route path="/metrics/new" element={<div className="metric-workspace"><MetricCreate/></div>}/><Route path="/metrics/:id" element={<div className="metric-workspace"><MetricDetail/></div>}/><Route path="/metrics/:id/sources" element={<div className="metric-workspace"><MetricSources/></div>}/><Route path="/metrics/:id/verify" element={<div className="metric-workspace"><MetricVerify/></div>}/><Route path="/metrics/:id/history" element={<div className="metric-workspace"><MetricHistory/></div>}/><Route path="/metrics/:id/observation/:number" element={<div className="metric-workspace"><MetricReport/></div>}/><Route path="/explore" element={<Collection/>}/><Route path="/dashboard" element={<Collection mode="dashboard"/>}/><Route path="/my-work" element={<Collection mode="my-work"/>}/><Route path="/activity" element={<Activity/>}/><Route path="/create" element={<Create/>}/><Route path="/milestone/:id" element={<Detail/>}/><Route path="/milestone/:id/submit" element={<Evidence/>}/><Route path="/milestone/:id/verification" element={<VerificationPage/>}/><Route path="/how-it-works" element={<How/>}/><Route path="*" element={<NotFound/>}/></Routes></Shell></TransactionProvider></WalletProvider>}
